"""Explicit synthetic native route matrix; not a runtime quality scanner.

--fixtures reuses the small Writer/Calc files generated by v0.2 native QA.
The full installed catalog is requested for three BMPs. Every rejected target
is separately checked through direct, unfiltered LibreOffice for the first BMP.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import shutil
import struct
import subprocess
import sys
import threading
import time
from zipfile import ZipFile

ROOT=Path(__file__).resolve().parents[2]
sys.path[:0]=[str(ROOT),str(ROOT/'tests')]
from app_backend.converter_guard import ConverterGuard, GuardError, GuardLimits, LibreOfficeAdapter
from app_backend.libreoffice_engine import convert_path


def digest(path):
    with path.open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--work',required=True,type=Path)
    parser.add_argument('--fixtures',required=True,type=Path)
    args=parser.parse_args()
    work=args.work.resolve();work.mkdir(parents=True,exist_ok=False)
    sources=work/'fixtures';sources.mkdir()
    for i,(w,h) in enumerate(((64,40),(96,64),(128,80)),1):
        data=b'\x10\x60\xe0'*w*h
        (sources/f'L{i}.bmp').write_bytes(b'BM'+struct.pack('<IHHI',54+len(data),0,0,54)+
            struct.pack('<IiiHHIIiiII',40,w,h,1,24,0,len(data),3780,3780,0,0)+data)
    for name in ('writer.docx','calc.xlsx'):
        shutil.copyfile(args.fixtures/name,sources/name)
    shutil.copyfile(sources/'writer.docx',sources/'renamed.bmp')
    (sources/'plain.unlisted').write_text('GUARD_NATIVE_UNLISTED\n')
    hashes={p.name:digest(p) for p in sources.iterdir()}

    class ObservedAdapter(LibreOfficeAdapter):
        def __init__(self):
            super().__init__();self.calls=[]
        def convert(self,source,target,*args,**kwargs):
            assert digest(source)==hashes[source.name]
            self.calls.append((source.name,target))
            return super().convert(source,target,*args,**kwargs)

    adapter=ObservedAdapter()
    assert adapter.available,'NOT_RUN: real installed LibreOffice required'
    assert adapter.capabilities([])['registryAvailable'],'NOT_RUN: point AIO_LIBREOFFICE at the real installation, not a wrapper without share/registry'
    # QA deadlines do not change application defaults (which remain None).
    guard=ConverterGuard(adapter=adapter,limits=GuardLimits(file_timeout=15),spool_parent=work)
    evidence={'scope':'Linux/source, synthetic route matrix; Windows NOT_RUN; no quality scanner',
        'engine':subprocess.run([str(adapter.executable),'--version'],capture_output=True,
            text=True,check=True,timeout=15).stdout.strip(),'cases':[]}
    identities=[]

    def run_case(label, paths, formats):
        before=len(adapter.calls);started=time.monotonic()
        identity=guard.create([{'id':str(i),'name':p.name,'size':p.stat().st_size}
            for i,p in enumerate(paths)],formats)['jobId']
        identities.append(identity)
        for i,p in enumerate(paths):
            with p.open('rb') as stream:guard.upload(identity,str(i),stream,p.stat().st_size)
        guard.start(identity)
        deadline=time.monotonic()+360
        while time.monotonic()<deadline:
            state=guard.status(identity)
            if state['finished']:break
            time.sleep(.04)
        else:raise AssertionError('QA deadline reached')
        tasks=[t for f in state['files'] for t in f['targets']]
        assert all(t['code']=='NATIVE_ROUTE_UNAVAILABLE' and not t['libreOfficeStarted']
                   for t in tasks if t['state']=='skipped')
        row={'label':label,'requested':state['total'],'nativeAttempts':state['attempted'],
            'filtered':state['filtered'],'ready':sum(t['state']=='ready' for t in tasks),
            'errors':[{'file':f['name'],'target':t['format'],'code':t['code']}
                for f in state['files'] for t in f['targets'] if t['state']=='error'],
            'seconds':round(time.monotonic()-started,3)}
        assert len(adapter.calls)-before==state['attempted'],row
        evidence['cases'].append(row);print(json.dumps(row),flush=True)
        return state

    try:
        bmps=[sources/f'L{i}.bmp' for i in (1,2,3)]
        hints=adapter.capabilities([{'id':str(i),'name':p.name,'size':p.stat().st_size}
            for i,p in enumerate(bmps)])
        formats=[f['id'] for f in hints['formats']]
        state=run_case('three-bmps-entire-catalog',bmps,formats)
        assert state['filtered']>state['total']//2,state
        excluded=[t['format'] for t in state['files'][0]['targets'] if t['state']=='skipped']
        controls=[];false_denials=[]
        control=LibreOfficeAdapter(adapter.executable)
        for i,target in enumerate(excluded):
            directory=work/'direct-controls'/str(i)
            try:
                outputs=control.convert(bmps[0],target,directory,cancel=threading.Event(),
                    timeout=15,on_started=lambda:None)
                false_denials.append(target)
                controls.append({'target':target,'result':'OUTPUT_CREATED','outputs':len(outputs)})
            except GuardError as error:
                assert error.code in ('ENGINE_OUTPUT_MISSING','ENGINE_FAILED'),(target,error.code)
                controls.append({'target':target,'result':error.code})
            finally:shutil.rmtree(directory,ignore_errors=True)
            if (i+1)%10==0:print(json.dumps({'directControlsCompleted':i+1}),flush=True)
        assert not false_denials,('False denials',false_denials)
        evidence['directNegativeControls']={'checked':len(controls),'falseDenials':false_denials,'results':controls}

        mixed=run_case('mixed-models',[sources/'L1.bmp',sources/'writer.docx',sources/'calc.xlsx'],
                       ['pdf','docx','dbf','png'])
        assert mixed['filtered']==4 and mixed['attempted']==8,mixed
        assert mixed['state']=='ready',mixed
        renamed=run_case('docx-renamed-bmp',[sources/'renamed.bmp'],['pdf','docx','odt'])
        assert renamed['state']=='ready' and renamed['filtered']==0
        assert renamed['files'][0]['nativeRoute']['documentService']=='com.sun.star.text.TextDocument'
        unknown=run_case('unlisted-source',[sources/'plain.unlisted'],['pdf','txt'])
        assert unknown['state']=='ready' and unknown['filtered']==0

        # Redirecting stdout and observing a filter must not alter the PDF.
        from pypdf import PdfReader
        output=next(o for o in mixed['result']['outputs'] if o['fileId']=='1' and o['format']=='pdf')
        guarded=work/'guarded-writer.pdf'
        with guard.open_result(output['downloadUrl'].split('ticket=')[1]) as (stream,_,_):
            with guarded.open('wb') as target:shutil.copyfileobj(stream,target,64*1024)
        direct=convert_path(sources/'writer.docx','pdf',work/'direct-pdf',executable=adapter.executable)[0]
        a,b=PdfReader(guarded),PdfReader(direct)
        assert len(a.pages)==len(b.pages)==2
        assert [p.extract_text() for p in a.pages]==[p.extract_text() for p in b.pages]
        image_hashes=lambda reader:[[hashlib.sha256(img.data).hexdigest() for img in p.images] for p in reader.pages]
        assert image_hashes(a)==image_hashes(b)
        evidence['nativePDFBaseline']={'pages':2,'textEqual':True,'encodedImagesEqual':True}
        evidence['sourceBytesUnchangedAtEveryObservedLaunch']=True
        for identity in identities:
            current=guard.status(identity)
            if current['result'] and current['result'].get('downloadUrl'):
                guard.confirm_saved(identity,current['result']['downloadUrl'].split('ticket=')[1])
            guard.release(identity)
        assert guard.storage_stats()['jobs']==guard.storage_stats()['reservedBytes']==0
        assert not [t for t in threading.enumerate() if t.name=='aio-native-observation']
        assert all(digest(p)==hashes[p.name] for p in sources.iterdir())
        evidence.update(status='PASS',ownedJobsAfterRelease=0,reservedBytesAfterRelease=0,
                        observationThreadsAfterCompletion=0)
        (work/'evidence.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
        print(json.dumps({'status':'PASS','evidence':str(work/'evidence.json')}),flush=True)
    finally:guard.close()


if __name__=='__main__':main()
